450	
451	    fn stub_ctx(command_succeeds: bool, network_ok: bool) -> InstallerContext<'static> {
452	        let run_cmd: &'static dyn Fn(&str) -> bool = if command_succeeds {
453	            &|_| true
454	        } else {
455	            &|_| false
456	        };
457	        let net: &'static dyn Fn() -> bool = if network_ok { &|| true } else { &|| false };
458	        InstallerContext {
459	            run_command: run_cmd,
460	            check_network: net,
461	            prepend_path: &|_| {},
462	        }
463	    }
464	
465	    fn make_checker<'a>(
466	        registry: &'a RequirementRegistry,
467	        probe: &'a EnvironmentProbe,
468	        temp: &TempDir,
469	    ) -> GapChecker<'a> {
470	        GapChecker::new(registry, probe, temp.path())
471	    }
