1	//! Step execution with retry and interactive recovery.
2	//!
3	//! Extracted from `orchestrate.rs` to reduce its size. Contains the
4	//! execution lifecycle: spinner display, output capture, auto-retries,
5	//! and the interactive recovery menu.
6	
7	use std::collections::{HashMap, HashSet};
8	use std::path::Path;
9	use std::time::Instant;
10	
11	use tracing::warn;
12	
13	use crate::config::interpolation::InterpolationContext;
14	use crate::error::Result;
15	use crate::logging::{BivvyEvent, EventBus};
16	use crate::shell::OutputCallback;
17	use crate::steps::{execute_step, ExecutionOptions, ResolvedStep, StepResult, StepStatus};
18	use crate::ui::{format_duration, OutputMode, Prompt, PromptOption, PromptType, UserInterface};
19	
20	use super::diagnostic;
21	use super::display::StepDisplay;
22	use super::patterns::{self, FixSuggestion, StepContext};
23	use super::recovery::{self, RecoveryAction};
24	
25	/// Maximum total execution attempts per step (auto-retries + manual retries).
26	/// Prevents infinite loops when the recovery prompt always returns "retry"
27	/// (e.g., in test environments with MockUI).
28	const MAX_STEP_ATTEMPTS: u32 = 100;
29	
30	/// Result of executing a step with the retry/recovery loop.
31	pub(super) struct StepExecutionResult {
32	    /// The final step result.
33	    pub result: StepResult,
34	    /// Whether the user chose to skip in the recovery menu.
35	    pub skipped_by_user: bool,
36	    /// Whether the user chose to abort in the recovery menu.
37	    pub aborted: bool,
38	}
39	
40	/// Execute a step with retry and interactive recovery.
41	///
42	/// This handles the full execution lifecycle: spinner display, output capture,
43	/// auto-retries, and the interactive recovery menu (retry/fix/shell/skip/abort).
44	#[allow(clippy::too_many_arguments)]
45	pub(super) fn execute_step_with_recovery(
46	    step: &ResolvedStep,
47	    step_name: &str,
48	    step_number: &str,
49	    step_indent: usize,
50	    project_root: &Path,
51	    context: &InterpolationContext,
52	    base_env: &HashMap<String, String>,
53	    process_env: &HashMap<String, String>,
54	    needs_force: bool,
55	    dry_run: bool,
56	    interactive: bool,
57	    step_ctx: &StepContext<'_>,
58	    diagnostic_funnel: bool,
59	    workflow_state: &diagnostic::WorkflowState<'_>,
60	    ui: &mut dyn UserInterface,
61	    step_display: &mut dyn StepDisplay,
62	    event_bus: &mut EventBus,
63	) -> Result<StepExecutionResult> {
64	    let mut retry_count: u32 = 0;
65	    let mut fix_history: HashSet<String> = HashSet::new();
66	    let mut skipped_by_user = false;
67	    let mut aborted = false;
68	    #[allow(unused_assignments)]
69	    let mut final_result: Option<StepResult> = None;
70	
71	    // Outer loop: step execution (retry/fix re-enter here)
72	    'step_execution: loop {
73	        // Fresh spinner per attempt — hide command text for sensitive steps
74	        let display_command = if step.behavior.sensitive {
75	            "[SENSITIVE]".to_string()
76	        } else {
77	            step.execution.command.clone()
78	        };
79	        // Mount the transient region with the spinner. The step display
80	        // owns the live-output ring buffer.
81	        step_display.start_running(&display_command);
82	        let output_mode = step_display.output_mode();
83	        let output_callback: Option<OutputCallback> = step_display.live_output_callback();
84	
85	        let exec_options = ExecutionOptions {
86	            force: needs_force,
87	            dry_run,
88	            capture_output: output_callback.is_none(),
89	            ..Default::default()
90	        };
91	        let _ = step_number;
92	
93	        let step_start = Instant::now();
94	        let result = match execute_step(
95	            step,
96	            project_root,
97	            context,
98	            base_env,
99	            process_env,
100	            &exec_options,
101	            output_callback,
102	        ) {
103	            Ok(result) => result,
104	            Err(e) => {
105	                warn!("Step '{}' errored: {}", step_name, e);
106	                StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
107	            }
108	        };
109	
110	        // Emit StepOutput events for captured output
111	        if let Some(ref output) = result.output {
112	            for line in output.lines() {
113	                event_bus.emit(&BivvyEvent::StepOutput {
114	                    name: step_name.to_string(),
115	                    stream: "stdout".to_string(),
116	                    line: line.to_string(),
117	                });
118	            }
119	        }
120	
121	        let duration_str = format_duration(result.duration);
122	
123	        match result.status() {
124	            StepStatus::Completed => {
125	                let detail = if retry_count > 0 {
126	                    Some(format!("succeeded on retry (attempt {})", retry_count + 1))
127	                } else {
128	                    None
129	                };
130	                // Clear the transient region and write the final result
131	                // line into scrollback. The label is derived from the
132	                // status enum inside `finish`.
133	                step_display.finish(
134	                    StepStatus::Completed,
135	                    Some(result.duration),
136	                    detail.as_deref(),
137	                );
138	                let mut r = result;
139	                r.recovery_detail = detail;
140	                final_result = Some(r);
141	                break 'step_execution;
142	            }
143	            StepStatus::Skipped => {
144	                step_display.finish(StepStatus::Skipped, None, None);
145	                final_result = Some(result);
146	                break 'step_execution;
147	            }
148	            StepStatus::Failed => {
149	                step_display.finish(StepStatus::Failed, Some(result.duration), None);
150	                let _ = duration_str;
151	
152	                // Build combined error output for pattern matching and display
153	                let combined_output = result
154	                    .output
155	                    .as_deref()
156	                    .map(|s| s.trim())
157	                    .filter(|s| !s.is_empty())
158	                    .unwrap_or_else(|| result.error.as_deref().unwrap_or("Command failed"))
159	                    .to_string();
160	
161	                // Match against error recovery system
162	                let (fix, hint, resolutions) = if diagnostic_funnel {
163	                    let diag_ctx = diagnostic::StepContext {
164	                        name: step_ctx.name,
165	                        command: step_ctx.command,
166	                        requires: step_ctx.requires,
167	                        template: step_ctx.template,
168	                    };
169	                    let diag = diagnostic::diagnose(&combined_output, &diag_ctx, workflow_state);
170	                    // Collect all resolutions with confidence 0.1–0.29 as hint text
171	                    // (shown below error block, not in menu)
172	                    let hints: Vec<String> = diag
173	                        .resolutions
174	                        .iter()
175	                        .filter(|r| r.confidence >= 0.1 && r.confidence < 0.3)
176	                        .map(|r| r.label.clone())
177	                        .collect();
178	                    let hint = if hints.is_empty() {
179	                        None
180	                    } else {
181	                        Some(format!("You might try: {}", hints.join(", or ")))
182	                    };
183	                    (None, hint, diag.resolutions)
184	                } else {
185	                    let fix = patterns::find_fix(&combined_output, step_ctx);
186	                    let hint = patterns::find_hint(&combined_output, step_ctx);
187	                    (fix, hint, Vec::new())
188	                };
189	
190	                // Show error block — skip in non-interactive verbose
191	                // where output was already streamed to stdout
192	                let output_was_streamed =
193	                    !step_display.is_interactive() && output_mode == OutputMode::Verbose;
194	                if !output_was_streamed {
195	                    step_display.show_error_block(
196	                        &step.execution.command,
197	                        &combined_output,
198	                        hint.as_deref(),
199	                        step_indent,
200	                    );
201	                }
202	
203	                // allow_failure: record and move on, no recovery menu
204	                if step.behavior.allow_failure {
205	                    final_result = Some(result);
206	                    break 'step_execution;
207	                }
208	
209	                // Auto-retry before showing recovery menu
210	                if retry_count < step.execution.retry {
211	                    retry_count += 1;
212	                    step_display.message(&format!(
213	                        "{}Retrying... (attempt {}/{})",
214	                        " ".repeat(step_indent),
215	                        retry_count + 1,
216	                        step.execution.retry + 1
217	                    ));
218	                    continue 'step_execution;
219	                }
220	
221	                // Non-interactive: no recovery menu
222	                if !interactive {
223	                    final_result = Some(result);
224	                    break 'step_execution;
225	                }
226	
227	                // Safety: cap total attempts to prevent infinite loops
228	                // (e.g., in tests where MockUI defaults to "retry")
229	                if retry_count >= MAX_STEP_ATTEMPTS {
230	                    warn!(
231	                        "Step '{}' exceeded max recovery attempts ({})",
232	                        step_name, MAX_STEP_ATTEMPTS
233	                    );
234	                    final_result = Some(result);
235	                    break 'step_execution;
236	                }
237	
238	                // Interactive recovery menu
239	                handle_recovery_menu(
240	                    step,
241	                    step_name,
242	                    step_indent,
243	                    result,
244	                    &combined_output,
245	                    fix,
246	                    hint,
247	                    &resolutions,
248	                    diagnostic_funnel,
249	                    &mut fix_history,
250	                    &mut retry_count,
251	                    &mut skipped_by_user,
252	                    &mut aborted,
253	                    &mut final_result,
254	                    project_root,
255	                    base_env,
256	                    process_env,
257	                    ui,
258	                    step_display,
259	                    event_bus,
260	                )?;
261	                if final_result.is_some() {
262	                    break 'step_execution;
263	                }
264	                // If final_result is still None, recovery chose retry/fix → continue
265	                continue 'step_execution;
266	            }
267	            _ => {
268	                final_result = Some(result);
269	                break 'step_execution;
270	            }
271	        }
272	    }
273	
274	    Ok(StepExecutionResult {
275	        result: final_result.expect("step execution loop must produce a result"),
276	        skipped_by_user,
277	        aborted,
278	    })
279	}
280	
281	/// Handle the interactive recovery menu after a step failure.
282	///
283	/// Sets `final_result` if the user chose to skip or abort. Returns `Ok(())`
284	/// to let the caller decide whether to continue or break the execution loop.
285	#[allow(clippy::too_many_arguments)]
286	fn handle_recovery_menu(
287	    step: &ResolvedStep,
288	    step_name: &str,
289	    step_indent: usize,
290	    result: StepResult,
291	    combined_output: &str,
292	    fix: Option<FixSuggestion>,
293	    hint: Option<String>,
294	    resolutions: &[diagnostic::ResolutionCandidate],
295	    diagnostic_funnel: bool,
296	    fix_history: &mut HashSet<String>,
297	    retry_count: &mut u32,
298	    skipped_by_user: &mut bool,
299	    aborted: &mut bool,
300	    final_result: &mut Option<StepResult>,
301	    project_root: &Path,
302	    base_env: &HashMap<String, String>,
303	    process_env: &HashMap<String, String>,
304	    ui: &mut dyn UserInterface,
305	    step_display: &mut dyn StepDisplay,
306	    event_bus: &mut EventBus,
307	) -> Result<()> {
308	    let pad = " ".repeat(step_indent);
309	    event_bus.emit(&BivvyEvent::RecoveryStarted {
310	        step: step_name.to_string(),
311	        error: combined_output.to_string(),
312	    });
313	    let has_hint = hint.is_some();
314	    loop {
315	        let action = if diagnostic_funnel {
316	            recovery::prompt_recovery_multi(ui, step_name, resolutions, fix_history, step_indent)?
317	        } else {
318	            recovery::prompt_recovery(
319	                ui,
320	                step_name,
321	                fix.as_ref(),
322	                has_hint,
323	                fix_history,
324	                step_indent,
325	            )?
326	        };
327	
328	        match action {
329	            RecoveryAction::Retry => {
330	                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
331	                    step: step_name.to_string(),
332	                    action: "retry".to_string(),
333	                    command: None,
334	                });
335	                *retry_count += 1;
336	                return Ok(());
337	            }
338	            RecoveryAction::Fix(ref cmd) | RecoveryAction::CustomFix(ref cmd) => {
339	                let is_custom = matches!(action, RecoveryAction::CustomFix(_));
340	                let cmd = cmd.clone();
341	                if recovery::confirm_fix(ui, step_name, &cmd)? {
342	                    event_bus.emit(&BivvyEvent::RecoveryActionTaken {
343	                        step: step_name.to_string(),
344	                        action: if is_custom {
345	                            "custom_fix".to_string()
346	                        } else {
347	                            "fix".to_string()
348	                        },
349	                        command: Some(cmd.clone()),
350	                    });
351	                    let fix_ok = recovery::run_fix(&cmd, project_root, &step.env_vars.env)?;
352	                    fix_history.insert(cmd.clone());
353	                    if fix_ok {
354	                        step_display.message(&format!("{}Fix command succeeded.", pad));
355	                    } else {
356	                        step_display.message(&format!("{}Fix command failed.", pad));
357	                    }
358	                    *retry_count += 1;
359	                    return Ok(());
360	                }
361	                // User declined the fix — re-show recovery menu
362	            }
363	            RecoveryAction::Shell => {
364	                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
365	                    step: step_name.to_string(),
366	                    action: "shell".to_string(),
367	                    command: None,
368	                });
369	                step_display.message(&format!(
370	                    "{}Dropping to debug shell (exit to return)...",
371	                    pad
372	                ));
373	                let debug_env =
374	                    crate::steps::build_step_env(step, project_root, base_env, process_env)?;
375	                crate::shell::debug::spawn_debug_shell(step_name, project_root, &debug_env)?;
376	                // After shell exit, re-show recovery menu
377	            }
378	            RecoveryAction::Skip => {
379	                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
380	                    step: step_name.to_string(),
381	                    action: "skip".to_string(),
382	                    command: None,
383	                });
384	                *skipped_by_user = true;
385	                let mut r = result;
386	                r.recovery_detail = Some("skipped by user after failure".to_string());
387	                *final_result = Some(r);
388	                return Ok(());
389	            }
390	            RecoveryAction::Abort => {
391	                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
392	                    step: step_name.to_string(),
393	                    action: "abort".to_string(),
394	                    command: None,
395	                });
396	                *aborted = true;
397	                let mut r = result;
398	                r.recovery_detail = Some("aborted by user".to_string());
399	                *final_result = Some(r);
400	                return Ok(());
401	            }
402	        }
403	    }
404	}
405	
406	/// Convert a config-level PromptConfig into a UI Prompt.
407	pub(super) fn config_prompt_to_ui_prompt(config: &crate::config::schema::PromptConfig) -> Prompt {
408	    use crate::config::schema::PromptType as ConfigPromptType;
409	
410	    let default = config.default.as_ref().and_then(|v| match v {
411	        serde_yaml::Value::String(s) => Some(s.clone()),
412	        serde_yaml::Value::Bool(b) => Some(b.to_string()),
413	        serde_yaml::Value::Number(n) => Some(n.to_string()),
414	        _ => None,
415	    });
416	
417	    let prompt_type = match &config.prompt_type {
418	        ConfigPromptType::Select => PromptType::Select {
419	            options: config
420	                .options
421	                .iter()
422	                .map(|o| PromptOption {
423	                    label: o.label.clone(),
424	                    value: o.value.clone(),
425	                })
426	                .collect(),
427	        },
428	        ConfigPromptType::Multiselect => PromptType::MultiSelect {
429	            options: config
430	                .options
431	                .iter()
432	                .map(|o| PromptOption {
433	                    label: o.label.clone(),
434	                    value: o.value.clone(),
435	                })
436	                .collect(),
437	        },
438	        ConfigPromptType::Confirm => PromptType::Confirm,
439	        ConfigPromptType::Input => PromptType::Input,
440	    };
441	
442	    Prompt {
443	        key: config.key.clone(),
444	        question: config.question.clone(),
445	        prompt_type,
446	        default,
447	    }
448	}
