1	//! Dependency graph for step execution ordering.
2	
3	use std::collections::{HashMap, HashSet, VecDeque};
4	
5	use crate::error::{BivvyError, Result};
6	
7	/// How to handle skipping a step that has dependents.
8	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
9	pub enum SkipBehavior {
10	    /// Skip the step and all its dependents.
11	    #[default]
12	    SkipWithDependents,
13	    /// Don't skip - run the step anyway.
14	    RunAnyway,
15	    /// Skip only this step, attempt to run dependents.
16	    SkipOnly,
17	}
18	
19	/// Represents the dependency relationships between steps.
20	#[derive(Debug, Clone)]
21	pub struct DependencyGraph {
22	    /// Map of step name to its direct dependencies.
23	    dependencies: HashMap<String, HashSet<String>>,
24	    /// Map of step name to steps that depend on it.
25	    dependents: HashMap<String, HashSet<String>>,
26	    /// All step names in the graph.
27	    steps: HashSet<String>,
28	}
29	
30	impl DependencyGraph {
31	    /// Create a new dependency graph builder.
32	    pub fn builder() -> DependencyGraphBuilder {
33	        DependencyGraphBuilder::new()
34	    }
35	
36	    /// Get the direct dependencies of a step.
37	    pub fn dependencies_of(&self, step: &str) -> Option<&HashSet<String>> {
38	        self.dependencies.get(step)
39	    }
40	
41	    /// Get steps that depend on the given step.
42	    pub fn dependents_of(&self, step: &str) -> Option<&HashSet<String>> {
43	        self.dependents.get(step)
44	    }
45	
46	    /// Check if a step exists in the graph.
47	    pub fn contains(&self, step: &str) -> bool {
48	        self.steps.contains(step)
49	    }
50	
51	    /// Get all step names.
52	    pub fn steps(&self) -> &HashSet<String> {
53	        &self.steps
54	    }
55	
56	    /// Get the number of steps in the graph.
57	    pub fn len(&self) -> usize {
58	        self.steps.len()
59	    }
60	
61	    /// Check if the graph is empty.
62	    pub fn is_empty(&self) -> bool {
63	        self.steps.is_empty()
64	    }
65	
66	    /// Returns steps in topological order (dependencies before dependents).
67	    ///
68	    /// Uses alphabetical ordering as tie-breaker for determinism.
69	    /// Prefer `topological_order_stable` when a workflow step list is available.
70	    ///
71	    /// Returns an error if a cycle is detected.
72	    pub fn topological_order(&self) -> Result<Vec<String>> {
73	        self.topological_order_with_hint(None)
74	    }
75	
76	    /// Returns steps in topological order, using `preferred_order` to break
77	    /// ties among sibling steps (same dependency level). Falls back to
78	    /// alphabetical ordering for steps not in the preferred list.
79	    pub fn topological_order_stable(&self, preferred_order: &[String]) -> Result<Vec<String>> {
80	        self.topological_order_with_hint(Some(preferred_order))
81	    }
82	
83	    fn topological_order_with_hint(
84	        &self,
85	        preferred_order: Option<&[String]>,
86	    ) -> Result<Vec<String>> {
87	        // Build a position map for tie-breaking. Steps in preferred_order
88	        // sort by their position; unknown steps sort after all known ones,
89	        // then alphabetically among themselves.
90	        let position: HashMap<&str, usize> = preferred_order
91	            .map(|order| {
92	                order
93	                    .iter()
94	                    .enumerate()
95	                    .map(|(i, s)| (s.as_str(), i))
96	                    .collect()
97	            })
98	            .unwrap_or_default();
99	
100	        let sort_key = |name: &String| -> (usize, String) {
101	            match position.get(name.as_str()) {
102	                Some(&pos) => (pos, String::new()),
103	                None => (usize::MAX, name.clone()),
104	            }
105	        };
106	
107	        // Count incoming edges for each node
108	        let mut in_degree: HashMap<String, usize> = HashMap::new();
109	        for step in &self.steps {
110	            in_degree.insert(
111	                step.clone(),
112	                self.dependencies.get(step).map_or(0, |d| d.len()),
113	            );
114	        }
115	
116	        // Start with nodes that have no dependencies, sorted for determinism.
117	        let mut ready: Vec<String> = in_degree
118	            .iter()
119	            .filter(|(_, &degree)| degree == 0)
120	            .map(|(step, _)| step.clone())
121	            .collect();
122	        ready.sort_by_key(|s| sort_key(s));
123	        let mut queue: VecDeque<String> = ready.into_iter().collect();
124	
125	        let mut result = Vec::with_capacity(self.steps.len());
126	
127	        while let Some(step) = queue.pop_front() {
128	            result.push(step.clone());
129	
130	            // Reduce in-degree for all dependents, collecting newly-ready
131	            // ones in preferred/alphabetical order for determinism.
132	            if let Some(dependents) = self.dependents.get(&step) {
133	                let mut newly_ready = Vec::new();
134	                for dependent in dependents {
135	                    if let Some(degree) = in_degree.get_mut(dependent) {
136	                        *degree -= 1;
137	                        if *degree == 0 {
138	                            newly_ready.push(dependent.clone());
139	                        }
140	                    }
141	                }
142	                newly_ready.sort_by_key(|s| sort_key(s));
143	                for dep in newly_ready {
144	                    queue.push_back(dep);
145	                }
146	            }
147	        }
148	
149	        // If we haven't processed all nodes, there's a cycle
150	        if result.len() != self.steps.len() {
151	            let remaining: Vec<_> = in_degree
152	                .iter()
153	                .filter(|(_, &d)| d > 0)
154	                .map(|(s, _)| s.clone())
155	                .collect();
156	
157	            return Err(BivvyError::CircularDependency {
158	                cycle: remaining.join(" -> "),
159	            });
160	        }
161	
162	        Ok(result)
163	    }
164	
165	    /// Find a cycle in the graph, returning the path if one exists.
166	    pub fn find_cycle(&self) -> Option<Vec<String>> {
167	        #[derive(Clone, Copy, PartialEq)]
168	        enum State {
169	            Unvisited,
170	            Visiting,
171	            Visited,
172	        }
173	
174	        let mut state: HashMap<&str, State> = self
175	            .steps
176	            .iter()
177	            .map(|s| (s.as_str(), State::Unvisited))
178	            .collect();
179	
180	        let mut path: Vec<String> = Vec::new();
181	
182	        fn dfs<'a>(
183	            node: &'a str,
184	            graph: &'a DependencyGraph,
185	            state: &mut HashMap<&'a str, State>,
186	            path: &mut Vec<String>,
187	        ) -> Option<Vec<String>> {
188	            state.insert(node, State::Visiting);
189	            path.push(node.to_string());
190	
191	            if let Some(deps) = graph.dependencies.get(node) {
192	                for dep in deps {
193	                    match state.get(dep.as_str()) {
194	                        Some(State::Visiting) => {
195	                            // Found cycle - build the cycle path
196	                            let cycle_start = path.iter().position(|s| s == dep).unwrap();
197	                            let mut cycle: Vec<String> = path[cycle_start..].to_vec();
198	                            cycle.push(dep.clone());
199	                            return Some(cycle);
200	                        }
201	                        Some(State::Unvisited) | None => {
202	                            if let Some(cycle) = dfs(dep, graph, state, path) {
203	                                return Some(cycle);
204	                            }
205	                        }
206	                        Some(State::Visited) => {}
207	                    }
208	                }
209	            }
210	
211	            path.pop();
212	            state.insert(node, State::Visited);
213	            None
214	        }
215	
216	        for step in &self.steps {
217	            if state.get(step.as_str()) == Some(&State::Unvisited) {
218	                if let Some(cycle) = dfs(step, self, &mut state, &mut path) {
219	                    return Some(cycle);
220	                }
221	            }
222	        }
223	
224	        None
225	    }
226	
227	    /// Returns groups of steps that can execute in parallel.
228	    ///
229	    /// Each group contains steps whose dependencies are satisfied
230	    /// by all previous groups.
231	    pub fn parallel_groups(&self) -> Result<Vec<Vec<String>>> {
232	        // First ensure no cycles
233	        if let Some(cycle) = self.find_cycle() {
234	            return Err(BivvyError::CircularDependency {
235	                cycle: cycle.join(" -> "),
236	            });
237	        }
238	
239	        let mut groups: Vec<Vec<String>> = Vec::new();
240	        let mut completed: HashSet<String> = HashSet::new();
241	
242	        while completed.len() < self.steps.len() {
243	            let mut ready: Vec<String> = self
244	                .steps
245	                .iter()
246	                .filter(|s| !completed.contains(*s))
247	                .filter(|s| self.is_ready(s, &completed))
248	                .cloned()
249	                .collect();
250	
251	            if ready.is_empty() {
252	                break;
253	            }
254	
255	            // Sort for deterministic ordering
256	            ready.sort();
257	
258	            completed.extend(ready.iter().cloned());
259	            groups.push(ready);
260	        }
261	
262	        Ok(groups)
263	    }
264	
265	    /// Check if a step is ready to run given completed steps.
266	    pub fn is_ready(&self, step: &str, completed: &HashSet<String>) -> bool {
267	        match self.dependencies.get(step) {
268	            None => true,
269	            Some(deps) => deps.iter().all(|d| completed.contains(d)),
270	        }
271	    }
272	
273	    /// Get all transitive dependents of a step.
274	    ///
275	    /// Returns steps that depend on the given step, directly or indirectly.
276	    pub fn transitive_dependents(&self, step: &str) -> HashSet<String> {
277	        let mut result = HashSet::new();
278	        let mut to_visit = vec![step.to_string()];
279	
280	        while let Some(current) = to_visit.pop() {
281	            if let Some(dependents) = self.dependents.get(&current) {
282	                for dep in dependents {
283	                    if result.insert(dep.clone()) {
284	                        to_visit.push(dep.clone());
285	                    }
286	                }
287	            }
288	        }
289	
290	        result
291	    }
292	
293	    /// Given a set of steps to skip, compute which additional steps must be skipped.
294	    pub fn compute_skips(&self, skip: &HashSet<String>, behavior: SkipBehavior) -> HashSet<String> {
295	        match behavior {
296	            SkipBehavior::RunAnyway => HashSet::new(),
297	            SkipBehavior::SkipOnly => skip.clone(),
298	            SkipBehavior::SkipWithDependents => {
299	                let mut result = skip.clone();
300	                for step in skip {
301	                    result.extend(self.transitive_dependents(step));
302	                }
303	                result
304	            }
305	        }
306	    }
307	}
