309	/// Builder for constructing a DependencyGraph.
310	#[derive(Debug, Default)]
311	pub struct DependencyGraphBuilder {
312	    dependencies: HashMap<String, HashSet<String>>,
313	}
314	
315	impl DependencyGraphBuilder {
316	    /// Create a new builder.
317	    pub fn new() -> Self {
318	        Self::default()
319	    }
320	
321	    /// Add a step with its dependencies.
322	    pub fn add_step(mut self, name: impl Into<String>, depends_on: Vec<String>) -> Self {
323	        let name = name.into();
324	        self.dependencies
325	            .entry(name)
326	            .or_default()
327	            .extend(depends_on);
328	        self
329	    }
330	
331	    /// Build the dependency graph.
332	    ///
333	    /// Returns an error if any dependency references a non-existent step.
334	    pub fn build(self) -> Result<DependencyGraph> {
335	        // Collect all step names
336	        let steps: HashSet<String> = self.dependencies.keys().cloned().collect();
337	
338	        // Validate all dependencies exist
339	        for (step, deps) in &self.dependencies {
340	            for dep in deps {
341	                if !steps.contains(dep) {
342	                    return Err(BivvyError::ConfigValidationError {
343	                        message: format!("Step '{}' depends on unknown step '{}'", step, dep),
344	                    });
345	                }
346	            }
347	        }
348	
349	        // Build dependents map (reverse lookup)
350	        let mut dependents: HashMap<String, HashSet<String>> = HashMap::new();
351	        for step in &steps {
352	            dependents.insert(step.clone(), HashSet::new());
353	        }
354	
355	        for (step, deps) in &self.dependencies {
356	            for dep in deps {
357	                dependents.get_mut(dep).unwrap().insert(step.clone());
358	            }
359	        }
360	
361	        Ok(DependencyGraph {
362	            dependencies: self.dependencies,
363	            dependents,
364	            steps,
365	        })
366	    }
367	}
