            templates_with_requires.len(),
            expected_count,
            "Number of templates with requires changed. Update \
             builtin_templates_declare_correct_requires and this count.\n\
             Templates with requires:\n{}",
            templates_with_requires
                .iter()
                .map(|n| format!("  {}", n))
                .collect::<Vec<_>>()
                .join("\n")
        );
    }

    #[test]
    fn all_template_requires_exist_in_requirement_registry() {
        use crate::requirements::registry::RequirementRegistry;
        use std::collections::HashSet;

        let template_registry = Registry::new(None).unwrap();
        let req_registry = RequirementRegistry::new();
        let known: HashSet<&str> = req_registry.known_names().into_iter().collect();

        let mut missing: Vec<(String, String)> = Vec::new();

        for name in template_registry.all_template_names() {
            if let Some(template) = template_registry.get(&name) {
                for req in &template.step.requires {
                    if !known.contains(req.as_str()) {
                        missing.push((name.clone(), req.clone()));
                    }
                }
            }
        }

        assert!(
            missing.is_empty(),
            "Templates reference requirements not in the registry:\n{}",
            missing
                .iter()
                .map(|(t, r)| format!("  template '{}' requires unknown '{}'", t, r))
                .collect::<Vec<_>>()
                .join("\n")
        );
    }

    #[test]
    fn install_templates_are_resolvable() {
        let registry = Registry::new(None).unwrap();

        let install_templates = [
            "mise-install",
            "mise-ruby",
            "mise-node",
            "mise-python",
            "brew-install",
            "rust-install",
            "postgres-install",
            "redis-install",
            "docker-install",
        ];

        for name in install_templates {
            let template = registry.get(name).unwrap_or_else(|| {
                panic!("Install template '{}' not found in registry", name);
            });
            assert!(
                template.step.command.is_some(),
                "Install template '{}' has no command",
                name
            );
        }
    }

    #[test]
    fn registry_detection_order() {
        let registry = Registry::new(None).unwrap();
        let order = registry.detection_order();
        // Should return templates in detection order
        assert!(!order.is_empty());
    }

    #[test]
    fn validate_inputs_catches_missing_required() {
        let temp = TempDir::new().unwrap();
        let templates_dir = temp.path().join(".bivvy").join("templates").join("steps");
        fs::create_dir_all(&templates_dir).unwrap();

        let template = r#"
name: with-inputs
description: "Template with inputs"
category: test
inputs:
  required_input:
    description: "A required input"
    type: string
    required: true
step:
  command: "echo ${required_input}"
"#;
        fs::write(templates_dir.join("with-inputs.yml"), template).unwrap();

        let registry = Registry::new(Some(temp.path())).unwrap();
        let errors = registry
