    #[test]
    fn concurrent_stores_do_not_corrupt_cache() {
        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let root = root.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let source_id = format!("http:source-{}", i);
                    let content = format!("content-for-{}", i);
                    store
                        .store(&source_id, "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        // The cache entry must be loadable and internally consistent
        // (content matches what the metadata points to).
        let store = CacheStore::new(&root);
        let entry = store.load("http:source-0", "shared-template").unwrap();
        // At least one writer's entry should be valid — the important thing
        // is that load doesn't fail with a parse error from partial writes.
        // Different source_ids produce different paths, so each should exist.
        for i in 0..10 {
            let source_id = format!("http:source-{}", i);
            let loaded = store.load(&source_id, "shared-template").unwrap();
            assert!(
                loaded.is_some(),
                "entry for source-{} should be loadable",
                i
            );
            let loaded = loaded.unwrap();
            let content = store.read_content(&loaded).unwrap();
            assert_eq!(
                content,
                format!("content-for-{}", i),
                "content for source-{} should be consistent",
                i
            );
        }

        // Also test racing on the exact same key
        let handles: Vec<_> = (0..10)
            .map(|i| {
                let root = root.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let content = format!("race-content-{}", i);
                    store
                        .store("http:shared", "same-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        // The entry must be loadable without corruption
        let loaded = store
            .load("http:shared", "same-template")
            .unwrap()
            .expect("entry should exist after concurrent writes");
        let content = store.read_content(&loaded).unwrap();
        // Content should be one of the valid values, not a garbled mix
        assert!(
            content.starts_with("race-content-"),
            "content should be a complete write, got: {:?}",
            content
        );
    }

    #[test]
    fn no_temp_files_left_after_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        // No .tmp files should remain
        for entry in fs::read_dir(temp.path()).unwrap() {
            let path = entry.unwrap().path();
            let name = path.file_name().unwrap().to_string_lossy();
            assert!(
                !name.ends_with(".tmp"),
                "temp file should not remain: {:?}",
                path
            );
        }
    }
}

