//! Cache storage implementation.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

use super::entry::CacheEntry;

static WRITE_COUNTER: AtomicU64 = AtomicU64::new(0);

/// Write data to a file atomically by writing to a temporary sibling file
/// then renaming into place. This prevents concurrent readers from observing
/// partially-written content.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let counter = WRITE_COUNTER.fetch_add(1, Ordering::Relaxed);
    let tmp_name = format!(
        ".{}.{}.{}.tmp",
        path.file_name().unwrap_or_default().to_string_lossy(),
        std::process::id(),
        counter,
    );
    let tmp_path = path.with_file_name(tmp_name);

    fs::write(&tmp_path, data)
        .with_context(|| format!("Failed to write temp cache file {:?}", tmp_path))?;

    fs::rename(&tmp_path, path)
        .with_context(|| format!("Failed to rename temp file {:?} to {:?}", tmp_path, path))?;

    Ok(())
}

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

impl CacheStore {
    /// Create a new cache store.
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

